import Foundation

// Real activity files captured from a Mi Band 10 (2026-06-23) via the DEBUG fixture
// dump in BandSyncer.processActivityFiles. Each constant is the full reassembled file
// (7-byte fileId prefix + payload + trailing CRC-32) exactly as fed to the parser.
//
// Stored as hex string literals rather than resource files so the test bundle needs no
// resource-copy phase — the fixtures are self-contained and diff-friendly.

enum Fixtures {

    /// Daily summary, version 5, 69 bytes. id=b0f6396af40501, ts=2026-06-23T03:00:00Z.
    /// Decoded by hand: steps=1111, calories=200, SpO₂ avg/max/min=98, HR fields unset.
    static let dailySummaryV5 =
        "b0f6396af4050100c004f8dc57040000c70000000000000000ff00000000000000ff000000c8000000006257bb3a6a6257bb3a6a6200000000000613004b000117bb136798"

    /// Daily details (per-minute), version 4, 98 bytes. id=c0a93a6af40400,
    /// ts=2026-06-23T15:44:00Z. Five one-minute records. First minute carries SpO₂=97, stress=36.
    static let dailyDetailsV4Short =
        "c0a93a6af4040000fffff8cfffff000000e000000064e400612400000000000000e000000064e400000000000000000000e000000064e400000000000000000000e000000064e400000000000000000001e000005e64e400000000000000ebb99117"

    /// Daily details, version 4, 1058 bytes. id=b0aa3a6af40400, ts=2026-06-23T15:48:00Z.
    /// A fuller window with steps/HR present in several minutes.
    static let dailyDetailsV4Long =
        ""

    /// Daily summary header present but a near-empty details file, version 4, 18 bytes.
    /// id=3c000000f40400, ts at unix 60. Degenerate edge case (no minute records).
    static let dailyDetailsV4Empty =
        "3c000000f4040000fffff8cfffff3b40745d"

    /// Intra-workout sensor-detail file ids captured from a Mi Band 10 (2026-06-23). These are
    /// type=sports detail=details — the per-second series the band records during a workout
    /// (subtype 8 looks like HR, subtype 22 a larger sensor stream, one was 12 KB). They match
    /// NONE of the parser predicates, so before the ACK-everything fix they were fetched but never
    /// ACKed and the band re-offered them on every connection. Stored as the 7-byte id only — the
    /// payloads aren't needed to exercise the routing, and there is no parser to feed them to.
    static let sportsDetailIds: [String] = [
        "17153a6af403a0", // sports subtype=8  detail=details version=3
        "4398396af403a0", // sports subtype=8  detail=details
        "009b396af403a0", // sports subtype=8  detail=details
        "fe9c396af403a0", // sports subtype=8  detail=details
        "bf8e396af405d8", // sports subtype=22 detail=details version=5 (12150 bytes)
        "d4bb396af405d8", // sports subtype=22 detail=details (6235 bytes)
    ]

    /// Workout per-second HR detail, version 3, 563 bytes. id=7fe83a6af403a0,
    /// ts=2026-06-23T20:11:43Z. A real strengthTraining session (sport=308): 135 one-second
    /// samples (== the workout's duration), hr=0 for the first 18 s while the sensor acquires,
    /// then a 74→87→80 bpm curve (117 valid readings). CRC-32 validated.
    static let workoutHrDetailV3 =
        ""

    /// Decodes a hex string into Data. Asserts on malformed input (test-only).
    static func bytes(_ hex: String) -> Data {
        precondition(hex.count % 2 == 0, "hex must have even length")
        var out = Data(capacity: hex.count / 2)
        var idx = hex.startIndex
        while idx < hex.endIndex {
            let next = hex.index(idx, offsetBy: 2)
            guard let b = UInt8(hex[idx ..< next], radix: 16) else {
                preconditionFailure("invalid hex byte: \(hex[idx ..< next])")
            }
            out.append(b)
            idx = next
        }
        return out
    }
}
